use vstd::prelude::*;

verus! {

    /// Given two `Vec<u32>` of equal length, with every element of `arr2` non‐zero
    /// and each `arr1[i] % arr2[i]` fitting in a 32-bit signed integer,
    /// return a new `Vec<u32>` of the same length whose i-th entry is `arr1[i] % arr2[i]`.
    fn element_wise_module(arr1: &Vec<u32>, arr2: &Vec<u32>) -> (res: Vec<u32>)
        requires
            // lengths are equal
            arr1.len() == arr2.len(),
            // no zero divisor
            forall|i: nat| i < arr2.len() as nat ==> arr2[i] != 0,
            // each remainder fits in a signed 32-bit range
            forall|i: nat| i < arr1.len() as nat ==>
                (arr1[i] % arr2[i] <= i32::MAX as u32),
        ensures
            // result same length
            res.len() == arr1.len(),
            // elementwise correctness
            forall|i: nat| i < arr1.len() as nat ==>
                res[i] == arr1[i] % arr2[i],
    {
        // capture the common length as both usize and nat
        let n_usize = arr1.len();
        let n: nat = n_usize as nat;

        // we'll build up the result by pushing one element at a time
        let mut i_u32: u32 = 0;
        let mut res: Vec<u32> = Vec::new();

        // iterate i = 0 .. n_usize
        while i_u32 < n_usize as u32
            invariant
                // tracking the loop index
                (i_u32 as nat) <= n,
                // res.len() = i
                res.len() == i_u32 as usize,
                // for all 0 <= j < i, res[j] = arr1[j] % arr2[j]
                forall|j: nat| j < i_u32 as nat ==>
                    res[j] == arr1[j] % arr2[j],
            decreases
                // measure to prove termination
                n - (i_u32 as nat),
        {
            let idx: usize = i_u32 as usize;
            let a = arr1[idx];
            let b = arr2[idx];
            // by precondition, b != 0
            assert(b != 0);
            let m = a % b;
            // by precondition, m <= i32::MAX as u32
            res.push(m);
            i_u32 = i_u32 + 1;
        }

        res
    }

} // end of `verus!`

